from rcb_client import Robot
from PIL import Image
import numpy as np,json
r=Robot();o=r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True,video='none');
for k,v in o.last.items(): Image.fromarray(v).save('/app/output/'+k+'.png')
for k,v in o.last_depth.items(): print(k,'shape',v.shape,'samples',[(p,float(v[p])) for p in [(0,0),(100,100),(512,512),(900,900)] if p[0]<v.shape[0] and p[1]<v.shape[1]])
print(json.dumps(o.meta.get('cameras',{}),indent=2)[:8000])
